42	/**
43	 * Mostly used as a facade for all Petclinic controllers
44	 * Also a placeholder for @Transactional and @Cacheable annotations
45	 *
46	 * @author Michael Isvy
47	 * @author Vitaliy Fedoriv
48	 */
49	@Service
50	public class ClinicServiceImpl implements ClinicService {
51	
52	    /** Maximum number of owners allowed per city. */
53	    private static final long CITY_CAPACITY = 50L;
54	
55	    /** Maximum number of owners that may be created on a single day (by registration date). */
56	    private static final long DAILY_CAPACITY = 100L;
57	
58	    /** Above this many owners created today, reads carry a bulk-signup warning. */
59	    private static final long BULK_SIGNUP_THRESHOLD = 80L;
60	
61	    /** Fixed public holidays the business-day roll skips. */
62	    private static final Set<LocalDate> HOLIDAYS = Set.of(
63	        LocalDate.parse("2026-01-01"),
64	        LocalDate.parse("2026-01-26"),
65	        LocalDate.parse("2026-04-25"),
66	        LocalDate.parse("2026-12-25"),
67	        LocalDate.parse("2026-12-28"));
68	
69	    private final PetRepository petRepository;
70	    private final VetRepository vetRepository;
71	    private final OwnerRepository ownerRepository;
72	    private final VisitRepository visitRepository;
73	    private final SpecialtyRepository specialtyRepository;
74	    private final PetTypeRepository petTypeRepository;
75	    private final OwnerMapper ownerMapper;
76	
77	    public ClinicServiceImpl(
78	        PetRepository petRepository,
79	        VetRepository vetRepository,
80	        OwnerRepository ownerRepository,
81	        VisitRepository visitRepository,
82	        SpecialtyRepository specialtyRepository,
83	        PetTypeRepository petTypeRepository,
84	        OwnerMapper ownerMapper) {
85	        this.petRepository = petRepository;
86	        this.vetRepository = vetRepository;
87	        this.ownerRepository = ownerRepository;
88	        this.visitRepository = visitRepository;
89	        this.specialtyRepository = specialtyRepository;
90	        this.petTypeRepository = petTypeRepository;
91	        this.ownerMapper = ownerMapper;
92	    }
