154	    @Override
155	    @Transactional(readOnly = true)
156	    public Collection<Owner> findAllOwners() throws DataAccessException {
157	        Collection<Owner> owners = ownerRepository.findAll();
158	        return decorateWithHouseholdMemberCount(owners, owners);
