161	    @Override
162	    @Transactional(readOnly = true)
163	    public Page<Owner> findOwners(String lastName, Pageable pageable) throws DataAccessException {
164	        Page<Owner> owners = (lastName != null)
165	            ? ownerRepository.findByLastName(lastName, pageable)
166	            : ownerRepository.findAll(pageable);
167	        return decorateWithHouseholdMemberCount(owners, owners.getContent());
