170	    @Override
171	    @Transactional
172	    public void deleteOwner(Owner owner) throws DataAccessException {
173	        // Soft delete: retain the row, flag it deleted, so reads still return the owner and the
174	        // create endpoint's duplicate/identity checks can ignore it.
175	        owner.setDeleted(true);
176	        ownerRepository.save(owner);
177	    }
