205	    public Specialty findSpecialtyById(int specialtyId) {
206	        return findEntityById(() -> specialtyRepository.findById(specialtyId));
207	    }
208	
209	    @Override
210	    @Transactional(readOnly = true)
211	    public Collection<Specialty> findAllSpecialties() throws DataAccessException {
212	        return specialtyRepository.findAll();
213	    }
214	
215	    @Override
216	    @Transactional
217	    public void saveSpecialty(Specialty specialty) throws DataAccessException {
218	        specialtyRepository.save(specialty);
219	    }
