265	    @Override
266	    @Transactional
267	    public void saveOwner(Owner owner) throws DataAccessException {
268	        saveOwner(owner, false);
269	    }
270	
271	    @Override
272	    @Transactional
273	    public void saveOwner(Owner owner, boolean declaredHouseholdMember) throws DataAccessException {
274	        if (owner.isNew()) {
275	            LocalDate effectiveDate = owner.getRegistrationDate() != null
276	                ? owner.getRegistrationDate()
277	                : LocalDate.now();
278	            owner.setRegistrationDate(toBusinessDay(effectiveDate));
279	            if (owner.getHouseholdId() == null) {
280	                owner.setHouseholdId(householdIdFor(owner.getLastName(), owner.getPostcode()));
281	            }
282	            if (owner.getCustomerCode() == null) {
283	                owner.setCustomerCode(generateCustomerCode(owner));
284	            }
285	            if (owner.getNamesakeCount() == null) {
286	                owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
287	            }
288	            if (owner.getPossibleDuplicate() == null) {
289	                // A declared household member is not a suspected duplicate; otherwise flag it against
290	                // any existing member of the same household it collides with.
291	                Integer possibleDuplicateOf = declaredHouseholdMember ? null : findPossibleDuplicateOf(owner);
292	                owner.setPossibleDuplicateOf(possibleDuplicateOf);
293	                owner.setPossibleDuplicate(possibleDuplicateOf != null);
294	            }
295	            if (owner.getMembershipLevelCap() == null) {
296	                owner.setMembershipLevelCap(computeMembershipLevelCap(owner));
297	            }
298	        }
299	        ownerRepository.save(owner);
300	        decorateWithHouseholdMemberCount(owner);
301	    }
302	
303	    /**
304	     * Count the existing owners (before this create) that share the given first and last name,
305	     * compared case-insensitively, as required by the read-only {@code namesakeCount} field.
306	     */
307	    private int countNamesakes(String firstName, String lastName) {
308	        if (firstName == null || lastName == null) {
309	            return 0;
310	        }
311	        return (int) ownerRepository.findAll().stream()
312	            .filter(owner -> firstName.equalsIgnoreCase(owner.getFirstName())
313	                && lastName.equalsIgnoreCase(owner.getLastName()))
314	            .count();
315	    }
316	
317	    /**
318	     * Build a customer code formatted {@code '<REGION>-<HASH8>'}, where {@code REGION} is the
319	     * canonical region derived from the owner's postcode (falling back to the city-to-region
320	     * table, then {@code 'UNKNOWN'}, as resolved by {@link LocalityResolver}) and {@code HASH8}
321	     * is the first 8 upper-case hexadecimal characters of the SHA-256 digest over the owner's
322	     * normalized telephone concatenated with the last name (e.g. {@code 'NSW-1A2B3C4D'}).
323	     * <p>
324	     * If the computed code collides with an existing owner's {@code customerCode}, it is
325	     * de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that
326	     * makes it unique (e.g. {@code 'NSW-1A2B3C4D-2'}).
327	     */
328	    private String generateCustomerCode(Owner owner) {
329	        String region = LocalityResolver.resolve(owner.getCity(), owner.getPostcode());
330	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
331	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
332	        String base = region + "-" + Sha256Hex.upperHexPrefix(telephone + lastName, 8);
333	
334	        Set<String> existingCodes = ownerRepository.findAll().stream()
335	            .map(Owner::getCustomerCode)
336	            .filter(Objects::nonNull)
337	            .collect(Collectors.toSet());
338	        if (!existingCodes.contains(base)) {
339	            return base;
340	        }
341	        int n = 2;
342	        while (existingCodes.contains(base + "-" + n)) {
343	            n++;
344	        }
345	        return base + "-" + n;
346	    }
347	
348	    /**
349	     * Count the existing owners whose city matches the given city, compared case-insensitively,
350	     * used by the per-city capacity rule ({@link #isCityAtCapacity}).
351	     */
352	    private long countOwnersInCity(String city) {
353	        if (city == null) {
354	            return 0L;
355	        }
356	        return ownerRepository.findAll().stream()
357	            .filter(owner -> city.equalsIgnoreCase(owner.getCity()))
358	            .count();
359	    }
360	
361	    @Override
362	    @Transactional(readOnly = true)
363	    public boolean isCityAtCapacity(String city) throws DataAccessException {
364	        return countOwnersInCity(city) >= CITY_CAPACITY;
365	    }
366	
367	    @Override
368	    @Transactional(readOnly = true)
369	    public boolean isDailyRegistrationAtCapacity() throws DataAccessException {
370	        return countRegisteredToday() >= DAILY_CAPACITY;
371	    }
372	
373	    @Override
374	    @Transactional(readOnly = true)
375	    public boolean isBulkSignupDay() throws DataAccessException {
376	        return countRegisteredToday() > BULK_SIGNUP_THRESHOLD;
377	    }
378	
379	    /**
380	     * Count the owners whose registration date equals today's business day, used by the
381	     * daily create-limit and bulk-signup rules.
382	     */
383	    private long countRegisteredToday() {
384	        LocalDate businessDay = toBusinessDay(LocalDate.now());
385	        return ownerRepository.findAll().stream()
386	            .filter(owner -> businessDay.equals(owner.getRegistrationDate()))
387	            .count();
388	    }
389	
390	    /**
391	     * Rolls a registration date forward onto a business day: a Saturday, Sunday or listed public
392	     * holiday is advanced one day at a time until a non-holiday weekday is reached, while a plain
393	     * weekday is returned unchanged. Applied to the effective registration date (whether supplied
394	     * or defaulted to the server date) so that the stored {@code registrationDate}, every value
395	     * derived from it (such as the membership number's year segment) and the per-day create-limit
396	     * all use the adjusted business day.
397	     */
398	    private static LocalDate toBusinessDay(LocalDate date) {
399	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
400	            || date.getDayOfWeek() == DayOfWeek.SUNDAY
401	            || HOLIDAYS.contains(date)) {
402	            date = date.plusDays(1);
403	        }
404	        return date;
405	    }
406	
407	    @Override
408	    @Transactional(readOnly = true)
409	    public boolean isIdentityKeyInUse(Owner owner) throws DataAccessException {
410	        String identityKey = owner.getIdentityKey();
411	        return ownerRepository.findAll().stream()
412	            .filter(existing -> existing != owner)
413	            .filter(existing -> !existing.isDeleted())
414	            .map(Owner::getIdentityKey)
415	            .anyMatch(identityKey::equals);
416	    }
417	
418	    /**
419	     * Resolve the id of an existing owner that the given (not yet persisted) owner is a <em>possible</em>
420	     * duplicate of, or {@code null} when there is none. A possible duplicate belongs to an existing
421	     * owner's household (same computed {@code householdId}, i.e. same last name and postcode) while
422	     * carrying a different telephone, so it is not a hard duplicate (its identity key is unique) but is
423	     * worth flagging. When several existing owners match, the one with the lowest id is returned so the
424	     * result is deterministic. Computed once, at creation, to drive the read-only
425	     * {@code possibleDuplicate}/{@code possibleDuplicateOf} fields.
426	     */
427	    private Integer findPossibleDuplicateOf(Owner owner) {
428	        String householdId = owner.getHouseholdId();
429	        if (householdId == null) {
430	            return null;
431	        }
432	        return ownerRepository.findAll().stream()
433	            .filter(existing -> existing != owner && existing.getId() != null)
434	            .filter(existing -> !existing.isDeleted())
435	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
436	            .filter(existing -> !Objects.equals(owner.getTelephone(), existing.getTelephone()))
437	            .map(Owner::getId)
438	            .min(Integer::compareTo)
439	            .orElse(null);
440	    }
441	
442	    /**
443	     * Compute the membership-level ceiling for a new owner, as required by the level-cap rule: a new
444	     * owner's {@code membershipLevel} cannot exceed one above the current maximum membership level
445	     * among its household members (existing owners sharing the same {@code householdId}, excluding
446	     * soft-deleted ones and the owner itself). Returns one above that maximum, or {@code null} when
447	     * the owner has no household id or no existing household member, in which case no cap applies.
448	     *
449	     * <p>Each existing member's level is read through {@link OwnerMapper#formatMembershipLevel},
450	     * after decorating the members with their current household member counts, so the maximum
451	     * reflects the same effective (already-capped) level the API returns for those members.
452	     */
453	    private Integer computeMembershipLevelCap(Owner newOwner) {
454	        String householdId = newOwner.getHouseholdId();
455	        if (householdId == null) {
456	            return null;
457	        }
458	        List<Owner> members = ownerRepository.findAll().stream()
459	            .filter(existing -> existing != newOwner && existing.getId() != null)
460	            .filter(existing -> !existing.isDeleted())
461	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
462	            .collect(Collectors.toList());
463	        if (members.isEmpty()) {
464	            return null;
465	        }
466	        decorateWithHouseholdMemberCount(members, members);
467	        int maxLevel = members.stream()
468	            .mapToInt(member -> ownerMapper.formatMembershipLevel(member))
469	            .max()
470	            .getAsInt();
471	        return maxLevel + 1;
472	    }
473	
474	    @Override
475	    @Transactional(readOnly = true)
476	    public boolean isHouseholdInUse(Owner owner) throws DataAccessException {
477	        // Per the create endpoint's sharesHousehold contract, a household duplicate is an existing
478	        // owner with the same last name AND the same address (compared case-insensitively with runs
479	        // of whitespace collapsed). Owners that merely share a household id (same last name and
480	        // postcode) but live at different addresses are distinct members and are not duplicates, so
481	        // they may be created without declaring sharesHousehold.
482	        String lastNameKey = normalizeHouseholdValue(owner.getLastName());
483	        String addressKey = normalizeHouseholdValue(owner.getAddress());
484	        return ownerRepository.findAll().stream()
485	            .filter(existing -> existing != owner && existing.getId() != null)
486	            .filter(existing -> !existing.isDeleted())
487	            .anyMatch(existing -> lastNameKey.equals(normalizeHouseholdValue(existing.getLastName()))
488	                && addressKey.equals(normalizeHouseholdValue(existing.getAddress())));
489	    }
490	
491	    @Override
492	    @Transactional(readOnly = true)
493	    public String householdIdFor(String lastName, String postcode) throws DataAccessException {
494	        String key = normalizeHouseholdValue(lastName) + "|" + (postcode == null ? "" : postcode);
495	        return Sha256Hex.upperHexPrefix(key, 12);
496	    }
497	
498	    /**
499	     * Normalizes a household field (the last name) for duplicate comparison by trimming,
500	     * collapsing runs of whitespace to a single space and lower-casing, so differently cased or
501	     * spaced but equivalent values compare equal.
502	     */
503	    private static String normalizeHouseholdValue(String value) {
504	        if (value == null) {
505	            return "";
506	        }
507	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
508	    }
509	
510	    /**
511	     * Populate each given owner's transient {@code householdMemberCount} with the current number of
512	     * owners that share its {@code householdId}. Owners without a household id are left at a count
513	     * of zero.
514	     *
515	     * <p>The household sizes are computed in a single pass over the owner table regardless of how
516	     * many owners are being decorated, so decorating a whole page does not re-scan per element.
517	     */
518	    private <T> T decorateWithHouseholdMemberCount(T result, Collection<Owner> owners) {
519	        if (!owners.isEmpty()) {
520	            Map<String, Long> sizeByHousehold = ownerRepository.findAll().stream()
521	                .filter(owner -> owner.getHouseholdId() != null)
522	                .collect(Collectors.groupingBy(Owner::getHouseholdId, Collectors.counting()));
523	            for (Owner owner : owners) {
524	                long size = owner.getHouseholdId() == null
525	                    ? 0L
526	                    : sizeByHousehold.getOrDefault(owner.getHouseholdId(), 0L);
527	                owner.setHouseholdMemberCount((int) size);
528	            }
529	        }
530	        return result;
531	    }
532	
533	    /**
534	     * Decorate a single (possibly {@code null}) owner with its household member count and return it.
535	     */
536	    private Owner decorateWithHouseholdMemberCount(Owner owner) {
537	        return decorateWithHouseholdMemberCount(owner, owner == null ? List.of() : List.of(owner));
538	    }
539	
540	    @Override
541	    @Transactional(readOnly = true)
542	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
543	        Collection<Owner> owners = ownerRepository.findByLastName(lastName);
544	        return decorateWithHouseholdMemberCount(owners, owners);
545	    }
546	
547	    @Override
548	    @Transactional(readOnly = true)
549	    public Collection<Visit> findVisitsByPetId(int petId) {
550	        return visitRepository.findByPetId(petId);
551	    }
552	
553	    @Override
554	    @Transactional(readOnly = true)
555	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
556	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
557	    }
558	
559	    private <T> T findEntityById(Supplier<T> supplier) {
560	        try {
561	            return supplier.get();
562	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
563	            // Just ignore not found exceptions for Jdbc/Jpa realization
564	            return null;
565	        }
566	    }
567	
568	}
