249	        return this.householdMemberCount;
250	    }
251	
252	    public void setHouseholdMemberCount(Integer householdMemberCount) {
253	        this.householdMemberCount = householdMemberCount;
254	    }
255	
256	    /**
257	     * The owner's derived identity key, {@code normalizedTelephone + '|' + (email or empty) + '|' +
258	     * (householdId or empty)}. This single key is the sole criterion for duplicate detection on
259	     * creation: a new owner is rejected with 409 only when its whole identity key equals an existing
260	     * owner's. Because the telephone is part of the key, two members of the same household (same
261	     * {@code householdId}) with different telephones have distinct identity keys and are both
262	     * allowed; only an exact full-key match is a duplicate. The telephone and email components are
263	     * already held in their normalized forms (canonical E.164 and lower-cased) on every write path,
264	     * so the key is comparable across owners. Not persisted: it is computed from the current fields.
265	     */
266	    @Transient
267	    public String getIdentityKey() {
268	        String telephoneOrEmpty = this.telephone == null ? "" : this.telephone;
269	        String emailOrEmpty = this.email == null ? "" : this.email;
270	        String householdOrEmpty = this.householdId == null ? "" : this.householdId;
271	        return telephoneOrEmpty + "|" + emailOrEmpty + "|" + householdOrEmpty;
272	    }
273	
274	    /**
275	     * Stamp the owner's registration date with the server's current date on first
276	     * persist when none was supplied, so the default applies on every create path.
277	     */
278	    @PrePersist
279	    protected void onCreate() {
280	        if (this.registrationDate == null) {
281	            this.registrationDate = LocalDate.now();
282	        }
283	    }
284	
285	    protected Set<Pet> getPetsInternal() {
286	        if (this.pets == null) {
287	            this.pets = new HashSet<>();
288	        }
289	        return this.pets;
290	    }
291	
292	    protected void setPetsInternal(Set<Pet> pets) {
293	        this.pets = pets;
294	    }
295	
296	    public List<Pet> getPets() {
297	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
298	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
299	        return Collections.unmodifiableList(sortedPets);
300	    }
301	
302	    public void setPets(List<Pet> pets) {
303	        this.pets = new HashSet<>(pets);
304	    }
305	
306	    public void addPet(Pet pet) {
307	        getPetsInternal().add(pet);
308	        pet.setOwner(this);
309	    }
310	
311	    /**
312	     * Return the Pet with the given name, or null if none found for this Owner.
313	     *
314	     * @param name to test
315	     * @return true if pet name is already in use
316	     */
317	    public Pet getPet(String name) {
318	        return getPet(name, false);
319	    }
320	
321	    /**
322	     * Return the Pet with the given name, or null if none found for this Owner.
323	     *
324	     * @param name to test
325	     * @return true if pet name is already in use
326	     */
327	    public Pet getPet(String name, boolean ignoreNew) {
328	        name = name.toLowerCase();
329	        for (Pet pet : getPetsInternal()) {
330	            if (!ignoreNew || !pet.isNew()) {
331	                String compName = pet.getName();
332	                compName = compName.toLowerCase();
333	                if (compName.equals(name)) {
334	                    return pet;
335	                }
336	            }
337	        }
338	        return null;
339	    }
340	
341	    public Pet getPet(Integer petId) {
342	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
343	    }
344	
